func TestReproUnbufferedDeadlock(t *testing.T) {
	done := make(chan struct{})
	ch := make(chan Result) // no buffer
	go func() { ch <- Result{}; close(done) }()
	select {
	case <-done: t.Fatal("expected blocking send")
	case <-time.After(200 * time.Millisecond): // deadlock confirmed
	}
}
